"use client";
// @zeus-internal
import { CheckCheck, ClipboardCheck, RotateCcw } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useEffect, useId, useRef, useState } from "react";
import { ArtemisButton } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { type ApprovalDecision, type ApprovalRequest, CURRENT_REVIEWER, DECISION_PAST, INITIAL_REQUESTS, matchesQuery, } from "./01-review/data";
import { FilterTabs } from "./01-review/filter-tabs";
import { ArtemisMorphicTooltip, ArtemisMorphicTooltipProvider } from "./01-review/morphic-tooltip";
import { RequestRow } from "./01-review/request-row";
import { ReviewDialogContent } from "./01-review/review-dialog";
import { ReviewModal } from "./01-review/review-modal";
import { SearchField } from "./01-review/search-field";
type QueueTab = "pending" | "reviewed" | "all";
const LIST_FADE = { duration: 0.1, ease: ARTEMIS_EASE_OUT } as const;
function inTab(request: ApprovalRequest, tab: QueueTab) {
    if (tab === "all")
        return true;
    return tab === "pending" ? request.status === "pending" : request.status !== "pending";
}
function EmptyState({ searching, tab, onClear }: {
    searching: boolean;
    tab: QueueTab;
    onClear: () => void;
}) {
    const [title, body] = searching
        ? ["No matching requests", "Try another title, category, or teammate."]
        : tab === "reviewed"
            ? ["No reviewed requests", "Completed reviews will appear here."]
            : ["You're all caught up", "New requests will appear here when they need a decision."];
    return (<div className="art:flex art:min-h-96 art:flex-col art:items-center art:justify-center art:gap-3 art:px-4 art:text-center">
      <span aria-hidden="true" className="art:flex art:size-12 art:items-center art:justify-center art:rounded-full art:border art:border-border art:text-muted-foreground">
        <CheckCheck aria-hidden="true" className="art:size-5"/>
      </span>
      <p className="art:text-sm art:font-medium">{title}</p>
      <p className="art:max-w-xs art:text-xs art:text-muted-foreground">{body}</p>
      {searching ? (<ArtemisButton variant="tertiary" size="md" className="art:h-9 art:px-3 art:text-xs" onClick={onClear}>
          Clear search
        </ArtemisButton>) : null}
    </div>);
}
export default function ApprovalQueueReview() {
    const id = useId();
    const reduce = useReducedMotion();
    const sectionRef = useRef<HTMLElement>(null);
    const searchRef = useRef<HTMLInputElement>(null);
    const lastOpenedId = useRef<string | null>(null);
    const [requests, setRequests] = useState<ApprovalRequest[]>(INITIAL_REQUESTS);
    const [tab, setTab] = useState<QueueTab>("pending");
    const [query, setQuery] = useState("");
    const [openId, setOpenId] = useState<string | null>(null);
    const [dialogOpen, setDialogOpen] = useState(false);
    const [announcement, setAnnouncement] = useState("");
    const pendingCount = requests.filter((request) => request.status === "pending").length;
    const visible = requests.filter((request) => inTab(request, tab) && matchesQuery(request, query));
    const openRequest = openId ? requests.find((request) => request.id === openId) : undefined;
    const clearSearch = () => {
        setQuery("");
        searchRef.current?.focus();
    };
    const openReview = (requestId: string) => {
        lastOpenedId.current = requestId;
        setOpenId(requestId);
        setDialogOpen(true);
    };
    const [focusAfterClose, setFocusAfterClose] = useState(0);
    useEffect(() => {
        if (focusAfterClose === 0)
            return;
        const frame = window.requestAnimationFrame(() => {
            const root = sectionRef.current;
            if (!root)
                return;
            const requestId = lastOpenedId.current;
            const opener = requestId
                ? root.querySelector<HTMLElement>(`[data-approval-open="${CSS.escape(requestId)}"]`)
                : null;
            if (opener) {
                const active = document.activeElement;
                if (!active || active === document.body)
                    opener.focus();
                return;
            }
            (root.querySelector<HTMLElement>("[data-approval-open]") ?? searchRef.current)?.focus();
        });
        return () => window.cancelAnimationFrame(frame);
    }, [focusAfterClose]);
    const decide = (request: ApprovalRequest, decision: ApprovalDecision) => {
        setRequests((current) => current.map((item) => item.id === request.id
            ? { ...item, status: decision.action, review: { reviewer: CURRENT_REVIEWER, reviewedAt: "Just now", note: decision.note } }
            : item));
        setAnnouncement(`${request.title}: ${DECISION_PAST[decision.action]}.`);
    };
    return (<ArtemisMorphicTooltipProvider>
      <section ref={sectionRef} aria-labelledby={`${id}-title`} className="art:w-full art:max-w-4xl art:bg-background art:p-4 art:text-foreground art:@min-[640px]/artemis:p-6">
        <header className="art:mb-5 art:flex art:items-center art:justify-between art:gap-3">
          <div className="art:flex art:min-w-0 art:items-center art:gap-3">
            <span aria-hidden="true" className="art:flex art:size-10 art:shrink-0 art:items-center art:justify-center art:rounded-full art:border art:border-border art:text-muted-foreground">
              <ClipboardCheck aria-hidden="true" className="art:size-4"/>
            </span>
            <div className="art:min-w-0">
              <h2 id={`${id}-title`} className="art:truncate art:text-xl art:font-medium">
                Approval queue
              </h2>
              <p className="art:mt-1 art:text-xs art:text-muted-foreground">
                {pendingCount > 0 ? `${pendingCount} requests awaiting review` : "All requests reviewed"}
              </p>
            </div>
          </div>
          <ArtemisMorphicTooltip content="Reset preview">
            <ArtemisButton variant="ghost" size="icon" tabIndex={0} aria-label="Reset approval queue" onClick={() => setRequests(INITIAL_REQUESTS)} className="art:size-9 art:rounded-full art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">
              <RotateCcw aria-hidden className="art:size-4"/>
            </ArtemisButton>
          </ArtemisMorphicTooltip>
        </header>
        <div>
          <div className="art:mb-4 art:flex art:flex-wrap art:items-center art:justify-between art:gap-3">
            <FilterTabs<QueueTab> idBase={id} ariaLabel="Filter approval requests" value={tab} onValueChange={setTab} tabs={[
            { value: "pending", label: "Pending", count: pendingCount },
            { value: "reviewed", label: "Reviewed", count: requests.length - pendingCount },
            { value: "all", label: "All", count: requests.length },
        ]}/>
            <SearchField ref={searchRef} value={query} onValueChange={setQuery} onClear={clearSearch}/>
          </div>
          <div id={`${id}-results`} role="tabpanel" aria-labelledby={`${id}-${tab}`}>
            <div className="art:max-h-120 art:overflow-y-auto art:overscroll-contain art:p-1">
              <AnimatePresence mode="wait" initial={false}>
                <motion.div key={tab} className="art:min-h-96" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={reduce ? { duration: 0 } : LIST_FADE}>
                  {visible.length > 0 ? (<ul className="art:space-y-2.5">
                      {visible.map((request) => (<RequestRow key={request.id} request={request} onOpen={openReview}/>))}
                    </ul>) : (<EmptyState searching={query.trim().length > 0} tab={tab} onClear={clearSearch}/>)}
                </motion.div>
              </AnimatePresence>
            </div>
          </div>
        </div>
        <output aria-live="polite" className="art:sr-only">
          {announcement}
        </output>
        <ReviewModal open={dialogOpen && openRequest !== undefined} onClose={() => setDialogOpen(false)} onExitComplete={() => setFocusAfterClose((count) => count + 1)}>
          {openRequest ? (<ReviewDialogContent key={openRequest.id} request={openRequest} onDecision={decide} onClose={() => setDialogOpen(false)}/>) : null}
        </ReviewModal>
      </section>
    </ArtemisMorphicTooltipProvider>);
}

