"use client";
// @zeus-internal
import { motion, type Transition, useReducedMotion } from "motion/react";
import { type KeyboardEvent, type ReactNode, useId, useRef } from "react";
const BUTTON_ACTIVE = "art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:font-medium art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none art:text-foreground art:delay-100 art:rounded-full art:h-8 art:gap-1.5 art:px-3 art:py-0 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background";
const BUTTON_IDLE = "art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:font-medium art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none art:text-muted-foreground art:delay-0 art:hover:text-foreground art:rounded-full art:h-8 art:gap-1.5 art:px-3 art:py-0 art:text-xs art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background";
const INDICATOR_TRANSITION: Transition = { type: "spring", stiffness: 245, damping: 36, mass: 1.2 };
export type FilterTab<T extends string> = {
    value: T;
    label: string;
    count: number;
};
export function FilterTabs<T extends string>({ tabs, value, onValueChange, idBase, ariaLabel, }: {
    tabs: readonly FilterTab<T>[];
    value: T;
    onValueChange: (value: T) => void;
    idBase: string;
    ariaLabel: string;
}) {
    const layoutId = useId();
    const reduce = useReducedMotion();
    const refs = useRef<Array<HTMLButtonElement | null>>([]);
    const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
        let next = -1;
        if (event.key === "ArrowRight")
            next = (index + 1) % tabs.length;
        else if (event.key === "ArrowLeft")
            next = (index - 1 + tabs.length) % tabs.length;
        else if (event.key === "Home")
            next = 0;
        else if (event.key === "End")
            next = tabs.length - 1;
        if (next < 0)
            return;
        event.preventDefault();
        refs.current[next]?.focus();
        onValueChange(tabs[next].value);
    };
    return (<div role="tablist" className="art:inline-flex art:items-center art:rounded-full art:bg-muted art:gap-0.5 art:p-0.5" aria-label={ariaLabel}>
      {tabs.map((tab, index): ReactNode => {
            const active = tab.value === value;
            return (<div key={tab.value} className="art:relative">
            {active ? (<motion.span layoutId={layoutId} className="art:absolute art:inset-0 art:bg-background art:rounded-full" style={{ borderRadius: 9999 }} transition={reduce ? { duration: 0 } : INDICATOR_TRANSITION}/>) : null}
            <button ref={(node) => {
                    refs.current[index] = node;
                }} type="button" role="tab" aria-selected={active} className={active ? BUTTON_ACTIVE : BUTTON_IDLE} id={`${idBase}-${tab.value}`} aria-controls={`${idBase}-results`} tabIndex={active ? 0 : -1} onClick={() => onValueChange(tab.value)} onKeyDown={(event) => onKeyDown(event, index)}>
              {tab.label}
              <span className="art:tabular-nums art:text-muted-foreground">{tab.count}</span>
            </button>
          </div>);
        })}
    </div>);
}

"use client";
// @zeus-internal
import { animate, motion, type Transition, useMotionValue, useReducedMotion } from "motion/react";
import { createContext, type FocusEvent, type PointerEvent, type ReactNode, useCallback, useContext, useEffect, useId, useLayoutEffect, useMemo, useRef, useState, } from "react";
import { artemisCreatePortal } from "../../../../artemis-scope";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
const OPEN_DELAY = 180;
const CLOSE_DELAY = 80;
const WARM_WINDOW = 230;
const GAP = 10;
const EDGE = 12;
const INSTANT: Transition = { duration: 0 };
const WRAPPER_TRANSITION: Transition = { duration: 0.15, ease: ARTEMIS_EASE_OUT };
const LABEL_TRANSITION: Transition = {
    opacity: { duration: 0.14, ease: ARTEMIS_EASE_OUT },
    y: { type: "spring", duration: 0.42, bounce: 0.18 },
};
const MORPH_SPRING: Transition = { type: "spring", stiffness: 215, damping: 25, mass: 1.2, restDelta: 0.001 };
const SIZE_SPRING: Transition = { type: "spring", stiffness: 158, damping: 18, mass: 1, restDelta: 0.001 };
type Size = {
    width: number;
    height: number;
};
type Rect = {
    left: number;
    top: number;
    width: number;
};
const ESTIMATED_SIZE: Size = { width: 90, height: 30 };
type Arrival = "fresh" | "jump" | "morph";
type Tip = {
    id: string;
    content: ReactNode;
    anchor: HTMLElement;
    rect: Rect;
    instant: boolean;
    arrival: Arrival;
    seq: number;
    labelKey: number;
};
type TooltipApi = {
    enter: (id: string, content: ReactNode, el: HTMLElement) => void;
    focus: (id: string, content: ReactNode, el: HTMLElement) => void;
    hide: (id: string) => void;
};
const TooltipContext = createContext<TooltipApi | null>(null);
function rectOf(el: HTMLElement): Rect {
    const r = el.getBoundingClientRect();
    return { left: r.left, top: r.top, width: r.width };
}
export function ArtemisMorphicTooltipProvider({ children }: {
    children: ReactNode;
}) {
    const reduce = useReducedMotion() === true;
    const [tip, setTip] = useState<Tip | null>(null);
    const [open, setOpen] = useState(false);
    const tipRef = useRef<Tip | null>(null);
    const openRef = useRef(false);
    const seqRef = useRef(0);
    const labelKeyRef = useRef(0);
    const warmUntil = useRef(0);
    const openTimer = useRef<{
        id: string;
        handle: number;
    } | null>(null);
    const closeTimer = useRef<number | null>(null);
    const commit = useCallback((next: Tip | null) => {
        tipRef.current = next;
        setTip(next);
    }, []);
    const cancelOpen = useCallback(() => {
        if (openTimer.current)
            window.clearTimeout(openTimer.current.handle);
        openTimer.current = null;
    }, []);
    const cancelClose = useCallback(() => {
        if (closeTimer.current !== null)
            window.clearTimeout(closeTimer.current);
        closeTimer.current = null;
    }, []);
    const api = useMemo<TooltipApi>(() => {
        const reveal = (id: string, content: ReactNode, el: HTMLElement, instant: boolean) => {
            cancelOpen();
            cancelClose();
            const prev = tipRef.current;
            seqRef.current += 1;
            const sameTrigger = prev !== null && prev.id === id;
            if (!sameTrigger || instant)
                labelKeyRef.current += 1;
            commit({
                id,
                content,
                anchor: el,
                rect: rectOf(el),
                instant,
                arrival: prev ? "jump" : "fresh",
                seq: seqRef.current,
                labelKey: labelKeyRef.current,
            });
            openRef.current = true;
            setOpen(true);
        };
        return {
            enter(id, content, el) {
                const current = tipRef.current;
                if (openRef.current && current) {
                    cancelClose();
                    if (current.id === id)
                        return;
                    cancelOpen();
                    seqRef.current += 1;
                    commit({ ...current, id, content, anchor: el, rect: rectOf(el), instant: false, arrival: "morph", seq: seqRef.current });
                    return;
                }
                cancelOpen();
                if (current && performance.now() < warmUntil.current) {
                    reveal(id, content, el, false);
                    return;
                }
                openTimer.current = { id, handle: window.setTimeout(() => reveal(id, content, el, false), OPEN_DELAY) };
            },
            focus(id, content, el) {
                const current = tipRef.current;
                if (openRef.current && current?.id === id) {
                    cancelClose();
                    return;
                }
                reveal(id, content, el, true);
            },
            hide(id) {
                if (openTimer.current?.id === id)
                    cancelOpen();
                if (!openRef.current || tipRef.current?.id !== id || closeTimer.current !== null)
                    return;
                closeTimer.current = window.setTimeout(() => {
                    closeTimer.current = null;
                    openRef.current = false;
                    warmUntil.current = performance.now() + WARM_WINDOW;
                    setOpen(false);
                    if (tipRef.current?.instant)
                        commit(null);
                }, CLOSE_DELAY);
            },
        };
    }, [cancelOpen, cancelClose, commit]);
    useEffect(() => () => {
        cancelOpen();
        cancelClose();
    }, [cancelOpen, cancelClose]);
    const onExited = useCallback(() => {
        if (!openRef.current)
            commit(null);
    }, [commit]);
    return (<TooltipContext.Provider value={api}>
      {children}
      {tip ? artemisCreatePortal(<TooltipLayer tip={tip} open={open} reduce={reduce} onExited={onExited}/>, document.body) : null}
    </TooltipContext.Provider>);
}
function TooltipLayer({ tip, open, reduce, onExited }: {
    tip: Tip;
    open: boolean;
    reduce: boolean;
    onExited: () => void;
}) {
    const labelRef = useRef<HTMLDivElement>(null);
    const boxRef = useRef<HTMLDivElement>(null);
    const x = useMotionValue(0);
    const y = useMotionValue(0);
    const width = useMotionValue(0);
    const height = useMotionValue(0);
    const [size, setSize] = useState<Size | null>(null);
    const [mountedFresh] = useState(() => tip.arrival === "fresh" && !tip.instant);
    useLayoutEffect(() => {
        const label = labelRef.current;
        if (!label)
            return;
        const measure = () => {
            const box = label.getBoundingClientRect();
            const next = { width: Math.ceil(box.width), height: Math.ceil(box.height) };
            setSize((prev) => (prev && prev.width === next.width && prev.height === next.height ? prev : next));
        };
        if (tip.arrival === "fresh" && !tip.instant) {
            const frame = window.requestAnimationFrame(measure);
            return () => window.cancelAnimationFrame(frame);
        }
        measure();
        return undefined;
    }, [tip.seq, tip.arrival, tip.instant]);
